body:
### Tested versions

- Reproducible in: v4.8.dev1.official [ebbf577a0]

### System information

Godot v4.8.dev1 - Windows 11 (build 26200) - Multi-window, 2 monitors - Direct3D 12 (Forward+) - dedicated NVIDIA GeForce RTX 2080 (NVIDIA; 32.0.15.9186) - AMD Ryzen 5 9600X 6-Core Processor (12 threads) - 31.11 GiB memory - WASAPI (48000 Hz, Stereo/mono)

### Issue description

I'm using the new methods introduced by [this PR](https://github.com/godotengine/godot/pull/118973) to pass the mesh surface buffers as storage buffers to a compute shader, to avoid the CPU/GPU roundtrip. I'm able to write the vertex positions, normals or attributes, but I'm unable to bind the index buffer with the error `Storage buffer supplied (binding: 0) is invalid.`

After investigating, it seems the error is coming from here:

https://github.com/godotengine/godot/blob/master/servers/rendering/rendering_device.cpp#L4686-L4694

Since it only checks for `storage_buffer_owner` and `vertex_buffer_owner` to validate the RID, I assume it fails because
the index buffer is owned by `index_buffer_owner` as referenced here:

https://github.com/godotengine/godot/blob/master/servers/rendering/rendering_device.cpp#L4058-L4061

### Steps to reproduce

Here's a full code sample that I tested to reproduce the error, which should log the error message:
`ERROR: Storage buffer supplied (binding: 1) is invalid.`.
It works after removing the index buffer from the shader (but keeping the vertex buffer).

```gdscript
# Create a mesh with a single triangle
var mesh_arrays : Array
mesh_arrays.resize(Mesh.ARRAY_MAX)
mesh_arrays[ArrayMesh.ARRAY_VERTEX] = PackedVector3Array([Vector3(0.0, 0.0, 0.0), Vector3(0.0, 1.0, 0.0), Vector3(1.0, 0.0, 0.0)])
mesh_arrays[ArrayMesh.ARRAY_INDEX] = PackedInt32Array([0, 1, 2])

var mesh := ArrayMesh.new()
mesh.add_surface_from_arrays(
  Mesh.PRIMITIVE_TRIANGLES,
  mesh_arrays,
  [],
  {},
  Mesh.ARRAY_FLAG_USE_STORAGE_BUFFER # Note the usage of new flag to create the buffers as storage buffers
)

# Create a compute shader
const shader_code := """
#version 450

#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_int16 : require

layout(local_size_x = 2, local_size_y = 1, local_size_z = 1) in;

layout(set = 0, binding = 0, std430) restrict buffer VertexBuffer {
  float data[];
} vertex_buf;

layout(set = 0, binding = 1, std430) restrict buffer IndexBuffer {
  uint16_t indices[];
} index_buf;

void main() {

}
"""

var rd := RenderingServer.get_rendering_device()

# Compile shader
var shader_source: RDShaderSource = RDShaderSource.new()
shader_source.language = RenderingDevice.SHADER_LANGUAGE_GLSL
shader_source.source_compute = shader_code
var shader_spirv := rd.shader_compile_spirv_from_source(shader_source)
var shader_rid := rd.shader_create_from_spirv(shader_spirv)
var pipeline_rid := rd.compute_pipeline_create(shader_rid)

# Create uniforms
var vertex_buffer_rid := RenderingServer.mesh_surface_get_vertex_buffer_rd_rid(mesh.get_rid(), 0)
var vertex_uniform := RDUniform.new()
vertex_uniform.uniform_type = RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER
vertex_uniform.binding = 0
vertex_uniform.add_id(vertex_buffer_rid)

var index_buffer_rid := RenderingServer.mesh_surface_get_index_buffer_rd_rid(mesh.get_rid(), 0)
var index_uniform := RDUniform.new()
index_uniform.uniform_type = RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER
index_uniform.binding = 1
index_uniform.add_id(index_buffer_rid )

var uniform_set := rd.uniform_set_create([vertex_uniform, index_uniform], shader_rid, 0)

# Dispatch
var compute_list := rd.compute_list_begin()
rd.compute_list_bind_compute_pipeline(compute_list, pipeline_rid)
rd.compute_list_bind_uniform_set(compute_list, uniform_set, 0)
rd.compute_list_dispatch(compute_list, 1, 1, 1)
rd.compute_list_end()

```

